// checkpointTrailerLineRegex matches one whole Entire-Checkpoint trailer line,
// however the separator is spaced ("Entire-Checkpoint:<id>", a tab).
var checkpointTrailerLineRegex = regexp.MustCompile(`^` + CheckpointTrailerKey + `:\s*(` + checkpointID.CheckpointPattern + `)\s*$`)

// scissorsMarker is the core of git's scissors line ("# ---- >8 ----"); with
// `commit -v` everything below it is the diff, which git discards.
const scissorsMarker = "------------------------ >8 ------------------------"

// DefaultCommentPrefix is git's comment prefix when core.commentChar is unset.
const DefaultCommentPrefix = "#"

// autoCommentCandidates are the prefixes git tries, in order, for
// core.commentChar=auto.
const autoCommentCandidates = "#;@!$%^&|:"

// isScissorsLine reports whether line is git's scissors line for commentPrefix.
// Git cuts only at that exact line, never at prose that mentions the marker.
func isScissorsLine(line, commentPrefix string) bool {
	return strings.TrimSuffix(line, "\r") == commentPrefix+" "+scissorsMarker
}

// StripEditorComments returns an editor-written commit message without the
// lines git's default cleanup drops before the commit is recorded: everything
// from the scissors line down, and every line starting with commentPrefix. An
// empty commentPrefix, for a -m or -F message whose lines git keeps as
// written, returns message unchanged.
func StripEditorComments(message, commentPrefix string) string {
	if commentPrefix == "" {
		return message
	}
	lines := strings.Split(CutAtScissors(message, commentPrefix), "\n")
	kept := make([]string, 0, len(lines))
	for _, line := range lines {
		if !strings.HasPrefix(line, commentPrefix) {
			kept = append(kept, line)
		}
	}
	return strings.Join(kept, "\n")
}

// CutAtScissors returns message without git's scissors line for commentPrefix
// and everything below it, which git discards from a `commit -v` message. An
// empty commentPrefix returns message unchanged.
func CutAtScissors(message, commentPrefix string) string {
	if commentPrefix == "" {
		return message
	}
	lines := strings.Split(message, "\n")
	for i, line := range lines {
		if isScissorsLine(line, commentPrefix) {
			return strings.Join(lines[:i], "\n")
		}
	}
	return message
}

// AutoCommentPrefix returns the prefix git chose for core.commentChar=auto in a
// message it prepared for editing. Git picks it before adding its comment
// block, so it is read back from git's own lines: the scissors line if there is
// one, else the comment block that ends the message. A message without either
// (commit.status=false writes no block) gets DefaultCommentPrefix, unless its
// last line happens to start with a candidate.
func AutoCommentPrefix(message string) string {
	lines := strings.Split(message, "\n")
	for _, line := range lines {
		for _, candidate := range autoCommentCandidates {
			if isScissorsLine(line, string(candidate)) {
				return string(candidate)
			}
		}
	}
	for i := len(lines) - 1; i >= 0; i-- {
		if strings.TrimSpace(lines[i]) == "" {
			continue
		}
		if first := lines[i][:1]; strings.Contains(autoCommentCandidates, first) {
			return first
		}
		break
	}
	return DefaultCommentPrefix
}

// RemoveCheckpointTrailers removes every whole Entire-Checkpoint trailer line
// whose ID drop selects, anywhere between the subject paragraph and a scissors
// line, and returns the new message with the IDs removed (nil when the
// message is unchanged). It does not try to reproduce git's trailer-block
// rules (mixed blocks, a "(cherry picked from ...)" note, custom comment
// characters): a line that is exactly a checkpoint trailer is one in every
// form git accepts, and leaving one behind would let an amend keep a deleted
// checkpoint alive. Indentation is ignored, since a squash message indents
// the squashed commits' messages. Prose that merely mentions an ID is not a
// whole trailer line and stays. Blank lines a removal leaves doubled are
// collapsed, and trailing blank lines are trimmed unless a scissors line
// follows; nothing at or below the scissors line is touched.
func RemoveCheckpointTrailers(message string, drop func(checkpointID.CheckpointID) bool) (string, []checkpointID.CheckpointID) {
	lines := strings.Split(message, "\n")
	bodyStart := subjectParagraphEnd(lines)
	end := slices.IndexFunc(lines, func(line string) bool { return strings.Contains(line, scissorsMarker) })
	hasScissors := end >= 0
	if !hasScissors {
		end = len(lines)
	}
	removeLine := make([]bool, end)
	var removed []checkpointID.CheckpointID
	for i := bodyStart; i < end; i++ {
		match := checkpointTrailerLineRegex.FindStringSubmatch(strings.TrimSpace(lines[i]))
		if match == nil {
			continue
		}
		cpID, err := checkpointID.NewCheckpointID(match[1])
		if err != nil || !drop(cpID) {
			continue
		}
		removeLine[i] = true
		if !slices.Contains(removed, cpID) {
			removed = append(removed, cpID)
		}
	}
	if len(removed) == 0 {
		return message, nil
	}
	if hasScissors {
		kept := keepLines(lines[:end], removeLine, false, false)
		return strings.Join(append(kept, lines[end:]...), "\n"), removed
	}
	return strings.Join(keepLines(lines, removeLine, true, strings.HasSuffix(message, "\n")), "\n"), removed
}

// subjectParagraphEnd returns the index just past the subject paragraph: the
// first run of non-blank lines.
func subjectParagraphEnd(lines []string) int {
	i := 0
	for i < len(lines) && isBlankLine(lines[i]) {
		i++
	}
	for i < len(lines) && !isBlankLine(lines[i]) {
		i++
	}
	return i
}

// keepLines drops the removed lines and collapses a blank line that a
// removal would leave doubled. With trimTrailing it also trims trailing blank
// lines, keeping the message's final newline.
func keepLines(lines []string, removeLine []bool, trimTrailing, endsWithNewline bool) []string {
	kept := make([]string, 0, len(lines))
	afterRemoval := false
	for i, line := range lines {
		if removeLine[i] {
			afterRemoval = true
			continue
		}
		blank := isBlankLine(line)
		if blank && afterRemoval && len(kept) > 0 && isBlankLine(kept[len(kept)-1]) {
			continue
		}
		if !blank {
			afterRemoval = false
		}
		kept = append(kept, line)
	}
	if !trimTrailing {
		return kept
	}
	for len(kept) > 0 && isBlankLine(kept[len(kept)-1]) {
		kept = kept[:len(kept)-1]
	}
	if endsWithNewline {
		kept = append(kept, "")
	}
	return kept
}

func isBlankLine(line string) bool {
	return strings.TrimSpace(line) == ""
}

// FormatCheckpoint creates a commit message with a checkpoint trailer.
// This links user commits to their checkpoint metadata on entire/checkpoints/v1 branch.
func FormatCheckpoint(message string, cpID checkpointID.CheckpointID) string {
	return fmt.Sprintf("%s\n\n%s: %s\n", message, CheckpointTrailerKey, cpID.String())
}
---
// `Entire-OPF-Applied: true` trailer. Any other value (or absence) is
// treated as "OPF not applied" so the pre-push rewrite considers the
// commit a candidate for OPF redaction. Pinning the value to literal
// "true" — rather than just trailer presence — prevents a future
// "Entire-OPF-Applied: false" or "skipped" from accidentally meaning
// "yes, applied."
func HasOPFApplied(commitMessage string) bool {
	for _, line := range finalTrailerBlock(commitMessage) {
		key, value, ok := strings.Cut(line, ":")
		if !ok || key != OPFAppliedTrailerKey {
			continue
		}
		if strings.TrimSpace(value) == OPFAppliedTrailerValue {
			return true
		}
	}
	return false
}

func finalTrailerBlock(message string) []string {
	trimmed := strings.TrimRight(message, "\n")
	if trimmed == "" {
		return nil
	}
	lines := strings.Split(trimmed, "\n")
	i := len(lines) - 1
	for i >= 0 && strings.TrimSpace(lines[i]) == "" {
		i--
	}
	end := i + 1
	for i >= 0 && strings.TrimSpace(lines[i]) != "" {
		i--
	}
	start := i + 1
	// Git reads the first paragraph as the subject, never as trailers.
	if start == 0 || !isTrailerBlock(lines[start:end]) {
		return nil
	}
	return lines[start:end]
}

// isTrailerBlock reports whether lines form a trailer block: at least one
// trailer line, with every line either a trailer or an indented continuation
// of a preceding trailer's value. Both finalTrailerBlock and appendTrailerLine
// classify with this so the writer never joins onto a paragraph the readers reject.
func isTrailerBlock(lines []string) bool {
	seenTrailer := false
	for _, line := range lines {
		switch {
		case IsTrailerLine(line):
			seenTrailer = true
		case seenTrailer && (strings.HasPrefix(line, " ") || strings.HasPrefix(line, "\t")):
			// Git treats an indented line after a trailer as a continuation
			// of that trailer's value, never as a new trailer.
		default:
			return false
		}
	}
	return seenTrailer
}

// AppendOPFAppliedTrailer appends `Entire-OPF-Applied: true` in
// trailer-aware format. Idempotent: if the message already carries
// the trailer with value "true", the original message is returned
// unchanged so re-parenting an already-applied commit doesn't
// duplicate the trailer.
func AppendOPFAppliedTrailer(message string) string {
	if HasOPFApplied(message) {
		return message
	}
	trailer := fmt.Sprintf("%s: %s", OPFAppliedTrailerKey, OPFAppliedTrailerValue)
	return appendTrailerLine(message, trailer)
}

//   - "merge": skip trailer entirely (the merged commits keep their own)
//   - "squash": git's seeded squash message - inherits the squashed trailers, then matches as usual
//   - "commit": amend operation - preserves existing trailer or restores from LastCheckpointID
//

func (s *ManualCommitStrategy) PrepareCommitMsg(ctx context.Context, commitMsgFile string, source string) error {
	logCtx := logging.WithComponent(ctx, "checkpoint")

	// Skip during rebase, cherry-pick, or revert operations
	// These are replaying existing commits and should not be linked to agent sessions
	if isGitSequenceOperation(ctx) {
		logging.Debug(logCtx, "prepare-commit-msg: skipped during git sequence operation",
			slog.String("strategy", "manual-commit"),
			slog.String("source", source),
		)
		return nil
	}

	// A trailer naming a checkpoint deleted from this clone goes first: kept,
	// post-commit would condense into the dead ID and re-create it.
	strippedDeleted := stripDeletedCheckpointTrailers(ctx, commitMsgFile)

	// Inherited trailers link the squashed commits' checkpoints; matching still
	// runs so work the session holds gets a checkpoint of its own.
	inherited := s.inheritSquashedCheckpointTrailers(ctx, commitMsgFile, source)
	recordInheritedTrailers(ctx, inherited)

	// A merge commit is skipped: the merged commits keep their own trailers.
	if source == "merge" {
		logging.Debug(logCtx, "prepare-commit-msg: skipped for source",
			slog.String("strategy", "manual-commit"),
			slog.String("source", source),
		)
		return nil
	}

	// Handle amend (source="commit") separately: preserve or restore trailer
	if source == "commit" {
		return s.prepareAmendCommitMsg(ctx, commitMsgFile, strippedDeleted)
	}

	repo, err := openRepositoryTimed(ctx)
	if err != nil {
		return nil
	}
	defer repo.Close()
	// Commits redone after a reset are links too: their trailers ride along.
	inherited, redone := s.withRedoneTrailers(ctx, repo, commitMsgFile, source, inherited)
	if redone.onlyRedone() {
		return nil // everything staged is work the inherited checkpoints hold
	}

	_, findSessionsSpan := perf.Start(ctx, "find_sessions_for_worktree")
	worktreePath, err := paths.WorktreeRoot(ctx)
	if err != nil {
		findSessionsSpan.RecordError(err)
		findSessionsSpan.End()
		return nil
	}

	// Union of worktree matching and identity matching (the committing
	// process's ancestry) — see findSessionsForCommitLinking; neither
	// suppresses the other. We match by worktree (not BaseCommit) because
	// the user may have made intermediate commits without entering new
	// prompts, causing HEAD to diverge
	sessions, err := s.findSessionsForCommitLinking(ctx, worktreePath)
	if err != nil || len(sessions) == 0 {
		findSessionsSpan.RecordError(err)
		findSessionsSpan.End()
		// No active sessions or error listing - silently skip (hooks must be resilient)
		logging.Debug(logCtx, "prepare-commit-msg: no active sessions",
			slog.String("strategy", "manual-commit"),
			slog.String("source", source),
		)
		return nil
	}
	findSessionsSpan.End()

	// Fast path: skip content detection for mid-turn agent commits.
	if s.tryAgentCommitFastPath(ctx, commitMsgFile, sessions, source, inherited) {
		return nil
	}

	// Check if any session has new content to condense
	_, filterSessionsSpan := perf.Start(ctx, "filter_sessions_with_content")
	sessionsWithContent := s.filterSessionsWithNewContent(ctx, repo, sessions, redone)
	filterSessionsSpan.End()

	if len(sessionsWithContent) == 0 {
		// No new content — no trailer needed
		logging.Debug(logCtx, "prepare-commit-msg: no content to link",
			slog.String("strategy", "manual-commit"),
			slog.String("source", source),
			slog.Int("sessions_found", len(sessions)),
		)
		return nil
	}

	// Read current commit message
	_, readCommitMessageSpan := perf.Start(ctx, "read_commit_message")
	content, err := os.ReadFile(commitMsgFile) //nolint:gosec // commitMsgFile is provided by git hook
	if err != nil {
		readCommitMessageSpan.RecordError(err)
		readCommitMessageSpan.End()
		return nil
	}

	message := string(content)
	commentPrefix := editorCommentPrefix(ctx, source, message)

	// A trailer prepare already stamped is kept (e.g. amend); inherited ones are links
	if existingCpID, found := stampedTrailer(ctx, message, commentPrefix, inherited); found {
		readCommitMessageSpan.End()
		// Trailer already exists (e.g., amend) - keep it
		logging.Debug(logCtx, "prepare-commit-msg: trailer already exists",
			slog.String("strategy", "manual-commit"),
			slog.String("source", source),
			slog.String("existing_checkpoint_id", existingCpID.String()),
		)
		return nil
	}
	readCommitMessageSpan.End()

	// Resolve the checkpoint ID and session metadata.
	_, resolveMetadataSpan := perf.Start(ctx, "resolve_session_metadata")
	checkpointID, err := checkpointIDForSessions(ctx, sessionsWithContent)
	if err != nil {
		resolveMetadataSpan.RecordError(err)
		resolveMetadataSpan.End()
		return fmt.Errorf("failed to generate checkpoint ID: %w", err)
	}

	// Determine agent type and last prompt from session
	var agentType types.AgentType
	var lastPrompt string
	if len(sessionsWithContent) > 0 {

// inheritSquashedCheckpointTrailers handles a commit made while `git merge
// --squash` is in progress (SQUASH_MSG present): the squashed commits'
// Entire-Checkpoint trailers are carried into the message when a staged path is
// one the recorded commits changed. `commit -m` reports source "message", not "squash", so this runs
// before the source switch — but only for those two sources: an amend must
// keep its own logic even when an abandoned squash left SQUASH_MSG behind.
// Returns the inherited IDs; nil when there are none or the message is
// unusable. Ordinary matching runs afterwards either way.
func (s *ManualCommitStrategy) inheritSquashedCheckpointTrailers(ctx context.Context, commitMsgFile, source string) []id.CheckpointID {
	if source != commitSourceMessage && source != "squash" {
		return nil
	}
	logCtx := logging.WithComponent(ctx, "checkpoint")
	gitDir, err := GetGitDir(ctx)
	if err != nil {
		return nil
	}
	// SQUASH_MSG lives in the PER-WORKTREE git dir, like the sequencer markers.
	// The root is the shared registry handle (gitdir.OpenAt): never close it.
	root, err := gitdir.OpenAt(gitDir)
	if err != nil {
		return nil
	}
	squashMsg, err := osroot.ReadFileNoFollow(root, "SQUASH_MSG")
	if err != nil {
		return nil // no squash in progress (or unreadable: fall through to normal matching)
	}

	inherited := withoutDeletedCheckpoints(ctx, trailers.ParseAllCheckpoints(string(squashMsg)))
	if len(inherited) == 0 {
		return nil
	}
	repo, err := OpenRepository(ctx)
	if err != nil {
		return nil
	}
	defer repo.Close()
	if !squashTouchesStagedPath(ctx, repo, squashMsg) {
		stripInheritedCheckpointTrailers(commitMsgFile, inherited)
		logging.Debug(logCtx, "prepare-commit-msg: ignored stale squash message whose commits changed none of the staged paths",
			slog.String("source", source),
			slog.Int("inherited", len(inherited)))
		return nil
	}
	content, err := os.ReadFile(commitMsgFile) //nolint:gosec // commitMsgFile is provided by git hook
	if err != nil {
		return nil // nothing inherited; let ordinary matching report its own failure
	}
	message := string(content)
	present := make(map[string]bool)
	for _, cpID := range trailers.ParseAllCheckpoints(message) {
		present[cpID.String()] = true
	}
	commentPrefix := editorCommentPrefix(ctx, source, message)
	added := 0
	for _, cpID := range inherited {
		if present[cpID.String()] {
			continue
		}
		message = addInheritedCheckpointTrailer(message, cpID, commentPrefix)
		added++
	}
	if added == 0 {
		logging.Debug(logCtx, "prepare-commit-msg: squash in progress, message already carries the squashed trailers",
			slog.String("source", source),
			slog.Int("inherited", len(inherited)))
		return inherited
	}
	if err := os.WriteFile(commitMsgFile, []byte(message), 0o600); err != nil { //nolint:gosec // path from git hook arg
		return nil // nothing landed; hooks stay silent, ordinary matching may still try
	}
	logging.Info(logCtx, "prepare-commit-msg: inherited checkpoint trailers from the squashed commits",
		slog.String("strategy", "manual-commit"),
		slog.String("source", source),
		slog.Int("inherited", len(inherited)),
---redo
		// trailer links even when its checkpoint is missing here, but only a
		// checkpoint that exists may stand in for a fresh capture.
		for _, p := range matched[i] {
			if heldByCheckpoint && lastChangedBy[p] == i && sameModeAsTip(tipTree, p, staged[p]) {
				redonePaths[p] = true
			}
		}
		for _, cpID := range ids {
			if !seen[cpID] {
				seen[cpID] = true
				inherited = append(inherited, cpID)
			}
		}
	}
	if len(inherited) == 0 {
		logging.Debug(logCtx, "prepare-commit-msg: redone commits carry no matching trailers",
			slog.Int("replaced_commits", len(replaced)), slog.Int("staged", len(staged)))
		return redo{}
	}
	result := redo{ids: inherited, paths: redonePaths}
	for p := range staged {
		if !redonePaths[p] {
			result.others = append(result.others, p)
		}
	}
	slices.Sort(result.others)
	content, err := os.ReadFile(commitMsgFile) //nolint:gosec // commitMsgFile is provided by git hook
	if err != nil {
		return redo{}
	}
	message := string(content)
	present := make(map[id.CheckpointID]bool)
	for _, cpID := range trailers.ParseAllCheckpoints(message) {
		present[cpID] = true
	}
	commentPrefix := editorCommentPrefix(ctx, source, message)
	added := 0
	for _, cpID := range inherited {
		if !present[cpID] {
			message = addInheritedCheckpointTrailer(message, cpID, commentPrefix)
			added++
		}
	}
	if added > 0 {
		if err := os.WriteFile(commitMsgFile, []byte(message), 0o600); err != nil { //nolint:gosec // path from git hook arg
			return redo{}
		}
	}
	logging.Info(logCtx, "prepare-commit-msg: inherited checkpoint trailers from the commits being redone",
		slog.Int("replaced_commits", len(replaced)),
		slog.Int("inherited", len(inherited)),
---amend
		}
	}
	return false
}

// commitChangesAnyPath reports whether c changed one of wanted relative to its
// first parent (or added it, for a root commit).
func commitChangesAnyPath(c *object.Commit, wanted map[string]bool) bool {
	tree, err := c.Tree()
	if err != nil {
		return false
	}
	var parentTree *object.Tree
	if parent, err := c.Parents().Next(); err == nil {
		if parentTree, err = parent.Tree(); err != nil {
			return false
		}
	}
	changes, err := object.DiffTree(parentTree, tree)
	if err != nil {
		return false
	}
	for _, change := range changes {
		if wanted[change.To.Name] || wanted[change.From.Name] {
			return true
		}
	}
	return false
}

func stripInheritedCheckpointTrailers(commitMsgFile string, inherited []id.CheckpointID) {
	content, err := os.ReadFile(commitMsgFile) //nolint:gosec // commitMsgFile is provided by git hook
	if err != nil {
		return
	}
	remove := make(map[string]bool, len(inherited))
	for _, cpID := range inherited {
		remove[trailers.CheckpointTrailerKey+": "+cpID.String()] = true
	}
	lines := strings.Split(string(content), "\n")
	kept := lines[:0]
	for _, line := range lines {
		if !remove[strings.TrimSpace(line)] {
			kept = append(kept, line)
		}
	}
	if err := os.WriteFile(commitMsgFile, []byte(strings.Join(kept, "\n")), 0o600); err != nil { //nolint:gosec // path from git hook arg
		return // hooks stay silent on failure
	}
}

// handleAmendCommitMsg handles the prepare-commit-msg hook for amend operations
// (source="commit"). It preserves existing trailers or restores from LastCheckpointID.
func (s *ManualCommitStrategy) handleAmendCommitMsg(ctx context.Context, commitMsgFile string, strippedDeleted bool) error {
	logCtx := logging.WithComponent(ctx, "checkpoint")
	// Read current commit message
	content, err := os.ReadFile(commitMsgFile) //nolint:gosec // commitMsgFile is provided by git hook
	if err != nil {
		return nil
	}

	message := string(content)

	// If the final trailer block already has a live trailer, keep it unchanged;
	// an ID elsewhere in the message is not this commit's link. A deleted ID
	// still mentioned somewhere (not as a whole trailer line, so not stripped)
	// does not count: preserving on it would keep the dead checkpoint linked.
	if live := withoutDeletedCheckpoints(ctx, preparedFinalTrailers(message, gitCommentPrefix(ctx, message))); len(live) > 0 {
		logging.Debug(logCtx, "prepare-commit-msg: amend preserves existing trailer",
			slog.String("strategy", "manual-commit"),
			slog.String("checkpoint_id", live[0].String()),
		)
		return nil
	}
	if mentioned := trailers.ParseAllCheckpoints(message); len(mentioned) > 0 && len(withoutDeletedCheckpoints(ctx, mentioned)) == 0 {
		strippedDeleted = true
	}

	// No trailer in message — check if any session has LastCheckpointID to restore
	worktreePath, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return nil
	}

	sessions, err := s.findSessionsForWorktree(ctx, worktreePath)
	if err != nil || len(sessions) == 0 {
		return nil
	}

	// For amend, HEAD^ is the commit being amended, and HEAD is where we are now.
	// We need to match sessions whose BaseCommit equals HEAD (the commit being amended
	// was created from this base). This prevents stale sessions from injecting
	// unrelated checkpoint IDs.
	repo, repoErr := OpenRepository(ctx)
	if repoErr != nil {
		return nil
	}
	defer repo.Close()
	head, headErr := repo.Head()
	if headErr != nil {
		return nil
	}
	currentHead := head.Hash().String()

	// Find first matching session with LastCheckpointID to restore.
	// LastCheckpointID is set after condensation completes.
	for _, state := range sessions {
		if state.BaseCommit != currentHead {
			continue
		}
		if state.LastCheckpointID.IsEmpty() {
			continue
		}
		// A delete lists the ID before clearing it from session state, so an
		// amend racing that window must not restore it.
		if len(withoutDeletedCheckpoints(ctx, []id.CheckpointID{state.LastCheckpointID})) == 0 {
			continue
		}
		cpID := state.LastCheckpointID
		source := "LastCheckpointID"

		case !interactive.CanPromptInteractively():
			// No TTY (agent subprocess, CI) — auto-link without prompting
			message = addCheckpointTrailer(message, checkpointID)
		case commitLinking == settings.CommitLinkingAlways:
			// User previously chose "always" — auto-link without prompting
			message = addCheckpointTrailer(message, checkpointID)
		default:
			// Human at terminal — prompt interactively
			header := "Entire: Active " + string(agentType) + " session detected"
			var details []string
			if displayPrompt != "" {
				details = append(details, "Last prompt: "+displayPrompt)
			}

			logging.Info(logCtx, CommitLinkingPromptLogMsg,
				slog.String("strategy", "manual-commit"),
				slog.String("source", source),
			)
			result := askConfirmTTY(header, details, "Link this commit to session context?", true)
			if result == ttyResultSkip {
				logging.Debug(logCtx, "prepare-commit-msg: user declined trailer",
					slog.String("strategy", "manual-commit"),
					slog.String("source", source),
				)
				return nil
			}
			if result == ttyResultLinkAlways {
				// Persist preference so future commits auto-link (non-fatal if it fails)
				if saveErr := saveCommitLinkingAlways(ctx); saveErr != nil {
					logging.Warn(logCtx, "prepare-commit-msg: failed to save commit_linking=always",
						slog.String("error", saveErr.Error()),
					)
				}
			}
			message = addCheckpointTrailer(message, checkpointID)
		}
	default:
		// Normal editor flow: add trailer with explanatory comment (will be stripped by git)
		message = addCheckpointTrailerWithComment(message, checkpointID, string(agentType), displayPrompt, commentPrefix)
	}

	logging.Info(logCtx, "prepare-commit-msg: trailer added",
		slog.String("strategy", "manual-commit"),
		slog.String("source", source),
		slog.String("checkpoint_id", checkpointID.String()),
	)

	// Write updated message back
	_, writeCommitMessageSpan := perf.Start(ctx, "write_commit_message")
	if err := os.WriteFile(commitMsgFile, []byte(message), 0o600); err != nil { //nolint:gosec // path from git hook arg
		writeCommitMessageSpan.RecordError(err)
		writeCommitMessageSpan.End()
		return nil
	}
	writeCommitMessageSpan.End()

---
}

// addCheckpointTrailerWithComment adds the Entire-Checkpoint trailer with an explanatory comment.
// The trailer is placed above the git comment block but below the user's message area,
// with a comment explaining that the user can remove it if they don't want to link the commit
// to the agent session. If prompt is non-empty, it's shown as context. The comment is written
// with commentPrefix, the prefix git strips (see gitCommentPrefix).
func addCheckpointTrailerWithComment(message string, checkpointID id.CheckpointID, agentName, prompt, commentPrefix string) string {
	trailer := trailers.CheckpointTrailerKey + ": " + checkpointID.String()
	commentLines := []string{
		commentPrefix + " Remove the Entire-Checkpoint trailer above if you don't want to link this commit to " + agentName + " session context.",
	}
	if prompt != "" {
		commentLines = append(commentLines, commentPrefix+" Last Prompt: "+prompt)
	}
	commentLines = append(commentLines, commentPrefix+" The trailer will be added to your next commit based on this branch.")
	comment := strings.Join(commentLines, "\n")

	lines := strings.Split(message, "\n")

	// Find where the git comment block starts
	commentStart := -1
	for i, line := range lines {
		if strings.HasPrefix(line, commentPrefix) {
			commentStart = i
			break
		}
	}

	if commentStart == -1 {
		// No git comments, append trailer at the end
		return strings.TrimRight(message, "\n") + "\n\n" + trailer + "\n" + comment + "\n"
	}

	// Split into user content and git comments
	userContent := strings.Join(lines[:commentStart], "\n")
	gitComments := strings.Join(lines[commentStart:], "\n")

	// Build result: user content, blank line, trailer, comment, blank line, git comments
	userContent = strings.TrimRight(userContent, "\n")
	if userContent == "" {
		// No user content yet - leave space for them to type, then trailer
		// Two newlines: first for user's message line, second for blank separator
		return "\n\n" + trailer + "\n" + comment + "\n\n" + gitComments
	}
	return userContent + "\n\n" + trailer + "\n" + comment + "\n\n" + gitComments
}

